mapper.select:
SELECT requested.wind_code ,CASE WHEN si.security_source = 'temporary' THEN t.temp_security_market ELSE si.market END AS rawMarketCode ,si.security_source FROM (
SELECT CAST(#{code} AS CHAR(100)) AS wind_code
) requested LEFT JOIN rrs_securityinfo si ON si.wind_code = requested.wind_code LEFT JOIN rrs_temp_security_code t ON t.temp_security_code = requested.wind_code AND si.security_source = 'temporary' AND t.id = COALESCE(( SELECT history.id FROM rrs_temp_security_code history WHERE si.security_status = 'D' AND history.temp_security_code = t.temp_security_code AND history.sec_id = si.sec_id AND history.status = 'updated' AND history.is_deleted = 0 ORDER BY history.update_time DESC, history.id DESC LIMIT 1 ), t.id)

SELECT DISTINCT related.S_INFO_WINDCODE FROM ais_inv_ods.wind_windcustomcode current_code INNER JOIN ais_inv_ods.wind_windcustomcode related ON related.S_INFO_ISINCODE = current_code.S_INFO_ISINCODE WHERE current_code.S_INFO_WINDCODE = #{windCode} AND current_code.S_INFO_ISINCODE IS NOT NULL AND TRIM(current_code.S_INFO_ISINCODE) != '' AND current_code.EXCHMARKET IN
#{marketCode}
AND related.EXCHMARKET IN
#{marketCode}
AND NOT EXISTS ( SELECT 1 FROM rrs_securityinfo si WHERE si.wind_code = #{windCode} AND si.security_source = 'temporary' ) AND related.S_INFO_WINDCODE != #{windCode} AND related.S_INFO_WINDCODE IS NOT NULL AND TRIM(related.S_INFO_WINDCODE) != '' ORDER BY related.S_INFO_WINDCODE
